.darma-loader-darma-b13-server-rack { --accent: var(--loader-color, #22c55e); --accent-2: var(--loader-secondary-color, #f59e0b); width: calc(var(--loader-size, 112px) * .74); height: var(--loader-size, 112px); display: flex; flex-direction: column; gap: 4%; padding: 6%; border-radius: 6%; background: linear-gradient(#334155, #0b1220); box-shadow: inset 0 0 0 2px #475569; }
.darma-loader-darma-b13-server-rack span { position: relative; flex: 1; border-radius: 3px; background: rgba(255, 255, 255, .08); }
.darma-loader-darma-b13-server-rack span::before { content: ''; position: absolute; left: 7%; top: 32%; width: 44%; height: 34%; background: repeating-linear-gradient(90deg, rgba(255, 255, 255, .2) 0 11%, transparent 11% 22%); }
.darma-loader-darma-b13-server-rack span::after { content: ''; position: absolute; right: 9%; top: 34%; width: calc(var(--loader-size, 112px) * .045); height: calc(var(--loader-size, 112px) * .045); border-radius: 50%; background: var(--accent); box-shadow: calc(var(--loader-size, 112px) * -.085) 0 0 var(--accent-2), calc(var(--loader-size, 112px) * -.17) 0 0 var(--accent); animation: darma-loader-darma-b13-server-rack-rack-blink calc(var(--loader-speed, 1s) * 1.4) steps(2, end) infinite; }
.darma-loader-darma-b13-server-rack span:nth-child(2)::after { animation-delay: calc(var(--loader-speed, 1s) * .22); }
.darma-loader-darma-b13-server-rack span:nth-child(3)::after { animation-delay: calc(var(--loader-speed, 1s) * .44); }
.darma-loader-darma-b13-server-rack span:nth-child(4)::after { animation-delay: calc(var(--loader-speed, 1s) * .66); }
.darma-loader-darma-b13-server-rack span:nth-child(5)::after { animation-delay: calc(var(--loader-speed, 1s) * .88); }
@keyframes darma-loader-darma-b13-server-rack-rack-blink { 0%, 100% { opacity: .3; } 50% { opacity: 1; } }

